    if (i >= 0) return this.slots[i].seen;
    const w = this.walkSlotOf(id);
    if (w >= 0) return this.walkSlots[w].seen;
    const d = this.driveSlotOf(id);
    return d < 0 ? -1 : this.driveSlots[d].seen;
  }

  /* Dựng lại sau hibernation. seen lấy từ attachment nếu có; không có (attachment cũ) thì coi như vừa im lặng gần hết hạn:
     người còn bay có một chu kỳ nhịp sống để lên tiếng, người đã chết không được gia hạn thêm mỗi lần thức dậy */
  restore(list: { id: string; slot: number; name: string; seen?: number; kind?: 'walk' | 'drive'; ch?: number; veh?: number }[], now: number): void {
    for (const e of list) {
      const group = this.groupOf(e.kind === 'walk' || e.kind === 'drive' ? e.kind : 'fly');
      if (e.slot < 0 || e.slot >= group.length) continue;
      if (!this.conns.has(e.id)) this.conns.set(e.id, { stamps: [] });
      const seen = typeof e.seen === 'number' && Number.isFinite(e.seen) ? Math.min(e.seen, now) : now - P.slotTimeoutMs + P.heartbeatMs;
      const veh = e.kind === 'drive' ? exVehNorm(e.veh) : 0;   // attachment cũ không có veh: ô tô
      group[e.slot] = { id: e.id, name: e.name, seen, pos: null, dirty: false, ch: e.kind === 'walk' || veh === 1 ? exCharNorm(e.ch) : 0, veh };
    }
  }

  message(id: string, raw: string, now: number): Out[] {
    const conn = this.conns.get(id);
    if (!conn || typeof raw !== 'string' || raw.length > P.maxMsgBytes) return [];
    let m: any;
    try { m = JSON.parse(raw); } catch { return []; }
    if (!m || typeof m !== 'object') return [];
    const kind = this.kindOf(id);   // loại theo slot kết nối đang giữ, không theo trường trong gói
    const group = this.groupOf(kind);
    const slot = kind === null ? -1 : group.findIndex(s => s !== null && s.id === id);
    switch (m.t) {
      case 'join': return this.onJoin(id, kind !== null, m.name, m.kind === 'walk' || m.kind === 'drive' ? m.kind : 'fly', m.ch, m.veh, now);
      case 'leave': return this.release(id) ? [this.lobby()] : [];
      case 'hb': if (slot < 0) return []; group[slot].seen = now; return this.flush(now);
      case 'pos': return slot >= 0 ? this.onPos(conn, group[slot]!, slot, kind, m, now) : [];
      default: return [];
    }
  }

  // kind 'fly': tin trả lời không có trường kind (khách cũ hiểu được); 'walk' / 'drive' kèm kind; joined của 'drive' luôn vọng veh (khách xe máy dựa vào đó biết máy chủ hiểu xe máy)
  private onJoin(id: string, holding: boolean, rawName: unknown, kind: Kind, rawCh: unknown, rawVeh: unknown, now: number): Out[] {
    if (holding) return [];
    const k = kind === 'fly' ? {} : { kind };
    const name = typeof rawName === 'string' ? exSanitizeName(rawName) : null;
    if (name === null || exIsBad(name)) return [{ to: id, msg: { t: 'rejected', why: 'name', ...k } }];
    const group = this.groupOf(kind);
    const free = group.findIndex(s => s === null);
    if (free < 0) return [{ to: id, msg: { t: 'rejected', why: 'full', ...k } }];
    const veh = kind === 'drive' ? exVehNorm(rawVeh) : 0;   // khách cũ không gửi veh: ô tô
    group[free] = { id, name, seen: now, pos: null, dirty: false, ch: kind === 'walk' || veh === 1 ? exCharNorm(rawCh) : 0, veh };   // khách cũ không gửi ch: nam (đúng nhân vật họ tự thấy)
    return [{ to: id, msg: kind === 'drive' ? { t: 'joined', slot: free, kind, veh } : { t: 'joined', slot: free, ...k } }, this.lobby()];
  }

  private onPos(conn: Conn, s: Slot, slot: number, kind: Kind, m: any, now: number): Out[] {
    const { x, y, z, yaw, ts } = m;
    const walk = kind === 'walk', drive = kind === 'drive';
    const tilt = drive ? m.v : walk ? m.pose : m.bank;   // người lái gửi v + st, người đi dạo gửi pose, người bay gửi bank; trường của loại khác bị bỏ qua
    const st = drive ? m.st : 0;
    for (const v of [x, y, z, yaw, tilt, st]) if (typeof v !== 'number' || !Number.isFinite(v)) return [];
    conn.stamps = conn.stamps.filter(t => now - t < 1000);
    if (conn.stamps.length >= P.posMaxPerSec) return [];
    conn.stamps.push(now);
    s.seen = now;
    const stamp = typeof ts === 'number' && Math.abs(ts) <= Number.MAX_SAFE_INTEGER ? ts : now;   // ts ngoài ±2^53 (kể cả NaN/∞) coi như không gửi, tránh đẩy độ lệch giờ của khách thành ∞
    if (drive) {
      const D = P.drive, B = D.bounds;
      s.pos = [slot, clamp(x, B.x0, B.x1), clamp(y, D.yMin, D.yMax), clamp(z, B.z0, B.z1), wrapPi(yaw), clamp(tilt, -D.vMax, D.vMax), clamp(st, -D.steerMax, D.steerMax), stamp];
    } else if (walk) {
      const B = P.stroll.bounds;
      s.pos = [slot, clamp(x, B.x0, B.x1), clamp(y, P.stroll.yMin, P.stroll.yMax), clamp(z, B.z0, B.z1), wrapPi(yaw), clamp(Math.round(tilt), 0, P.stroll.poseMax), stamp];
    } else {
      s.pos = [slot, clamp(x, P.bounds.x0, P.bounds.x1), clamp(y, P.floor, P.ceiling), clamp(z, P.bounds.z0, P.bounds.z1), wrapPi(yaw), clamp(tilt, -P.bankMax, P.bankMax), stamp];
    }
    s.dirty = true;
    return this.flush(now);
  }

    const outs = this.room.connect(id, Date.now());
    if (outs === null) { server.close(1013, 'full'); return new Response(null, { status: 503 }); }
    this.dispatch(outs);
    return new Response(null, { status: 101, webSocket: client });
  }

  async webSocketMessage(ws: WebSocket, data: string | ArrayBuffer): Promise<void> {
    const a = ws.deserializeAttachment() as Att | null;
    if (!a || typeof data !== 'string') return;
    this.dispatch(this.room.message(a.id, data, Date.now()));
    await this.armAlarm();
  }

  async webSocketClose(ws: WebSocket): Promise<void> { this.drop(ws); }
  async webSocketError(ws: WebSocket): Promise<void> { this.drop(ws); }

  async alarm(): Promise<void> {
    this.armed = false;   // alarm đã chạy thì không còn alarm nào chờ
    this.dispatch(this.room.sweep(Date.now()));
    await this.armAlarm();
  }

  private drop(ws: WebSocket): void {
    const a = ws.deserializeAttachment() as Att | null;
    if (a) this.dispatch(this.room.disconnect(a.id));
  }

  // Gửi tin ra socket rồi ghi lại slot/tên/seen mới vào attachment (để sống sót qua hibernation); seen chỉ ghi khi cũ hơn heartbeatMs
  private dispatch(outs: Out[]): void {
    const socks = this.state.getWebSockets();
    for (const o of outs) {
      const text = JSON.stringify(o.msg);
      for (const ws of socks) {
        const a = ws.deserializeAttachment() as Att | null;
        if (!a || (o.to !== 'all' && o.to !== a.id)) continue;
        try { ws.send(text); } catch { /* socket đã đóng */ }
      }
      if (o.msg.t === 'lobby') {
        this.names = new Map(o.msg.flyers.map(f => [f.slot, f.name]));
        this.walkNames = new Map((o.msg.walkers ?? []).map(f => [f.slot, f.name]));
        this.driveNames = new Map((o.msg.drivers ?? []).map(f => [f.slot, f.name]));
      }
    }
    for (const ws of socks) {
      const a = ws.deserializeAttachment() as Att | null;
      if (!a) continue;
      const kind = this.room.kindOf(a.id);
      const walk = kind === 'walk', drive = kind === 'drive';
      const slot = walk ? this.room.walkSlotOf(a.id) : drive ? this.room.driveSlotOf(a.id) : this.room.slotOf(a.id);
      const name = slot >= 0 ? ((walk ? this.walkNames : drive ? this.driveNames : this.names).get(slot) ?? a.name) : '';
      const seen = this.room.seenOf(a.id);
      const stale = slot >= 0 && !(seen - (a.seen ?? -Infinity) < P.heartbeatMs);
      const k = walk ? 'walk' : drive ? 'drive' : undefined;   // loại ghi trong attachment; người bay không ghi (attachment như bản cũ)
      const ch = this.room.chOf(a.id), veh = this.room.vehOf(a.id);
      if (slot !== a.slot || name !== a.name || a.kind !== k || (a.ch ?? 0) !== ch || (a.veh ?? 0) !== veh || stale) {
        const next: Att = slot < 0 ? { id: a.id, slot, name } : k ? { id: a.id, slot, name, seen, kind: k } : { id: a.id, slot, name, seen };
        if (ch) next.ch = ch;
        if (veh) next.veh = veh;
        ws.serializeAttachment(next);
