        if (this.kind === 'drive' && this.veh === 1 && typeof m.veh !== 'number') { this.t?.send({ t: 'leave' }); this.offline(); return; }
        this.phase = 'flying'; this.mySlot = m.slot; this.mySlotWas = m.slot; this.notice = '';
